(async () => {
  // args[0] === "on" or "off" (DAE behavior)
  const hook = args[0];
  console.log("DAE args:", args);

  // DAE sometimes gives context as args[3] (you showed that), try that first,
  // otherwise try lastArg fallback.
  const context = args[3] ?? (args[args.length - 1] && args[args.length - 1].lastArg) ?? null;
  if (!context) return ui.notifications.error("无法取得 DAE 上下文 (args[3] / lastArg)。");

  // 解析目标 (token/actor) —— 使用 fromUuid 获取更稳健
  const tokenOrActor = await fromUuid(context.actorUuid ?? context.tokenUuid);
  const targetActor = tokenOrActor?.actor ? tokenOrActor.actor : tokenOrActor;
  // tokenOrActor 有可能是 token document（含 .token / .id），尽力拿到 scene token
  let targetToken = tokenOrActor?.token ?? canvas.tokens.get(tokenOrActor?.id) ?? canvas.tokens.placeables.find(t => t.actor?.id === targetActor?.id);

  // 解析施法者 actor UUID（origin 格式类似： Actor.<id>.Item.<id>.ActiveEffect...）
  const sourceActorUuid = context.origin ? context.origin.split(".Item.")[0] : null;
  const sourceTokenCandidate = await (sourceActorUuid ? fromUuid(sourceActorUuid) : null);
  const sourceActor = sourceTokenCandidate ? (sourceTokenCandidate.actor ?? sourceTokenCandidate) : null;
  // 在 scene 中尽量找到施法者 token（若施法者在当前场景）
  const sourceToken = canvas.tokens.placeables.find(t => t.actor?.id === sourceActor?.id) ?? null;

  if (!targetActor) return ui.notifications.error("无法解析目标 actor。");
  if (!sourceActor) ui.notifications.warn("未能解析施法者 actor，仍将以 null 作为来源（某些功能可能受限）。");

  if (hook === "off") {
    // 效果删除时什么都不做（按需求）
    return;
  }

  // ========== 计算施法者 DC ==========
  let dc = null;
  // 优先尝试系统里常见的 spelldc 字段
  dc =  (sourceActor?.system?.attributes?.spell.dc) ?? null;

  // 如果没拿到，就尝试更通用的计算：8 + proficiency + 施法属性 mod
  if (!dc) {
    // 尝试从施法物品（origin 的 Item 部分）读取 cast ability（若存在）
    let itemAbility = null;
    try {
      const originItemUuid = context.origin ? context.origin.split(".ActiveEffect")[0] : null; // Actor.x.Item.y
      if (originItemUuid) {
        const originItemWrapper = await fromUuid(originItemUuid);
        const originItem = originItemWrapper?.item ?? originItemWrapper;
        itemAbility = originItem?.system?.ability ?? originItem?.system?.save?.ability ?? originItem?.system?.spellcasting ?? null;
      }
    } catch (e) {
      console.warn("无法解析 origin item（可忽略，继续用回退 DC）", e);
    }

  }

  // ========== 让目标掷体质豁免 ==========
  // 使用 dnd5e 的 actor API：rollAbilitySave("con")
  const saveRoll = await targetActor.rollSavingThrow("con", { flavor: `体质豁免 — DC ${dc}` });
  const saveTotal = saveRoll?.total ?? 0;
  console.log("Save total:", saveTotal, "DC:", dc);

  // ========== 掷 5d10 伤害 ==========
  const damageDice = "5d10";
  const damageRoll = new Roll(damageDice);
  // Foundry v12+: 必须 await evaluate()（不要传 {async:true}）
  await damageRoll.evaluate();
  const rolledDamage = damageRoll.total ?? 0;
  console.log("Rolled damage (raw):", rolledDamage);

  // 根据豁免结果决定最终伤害（豁免成功减半，向下取整）
  let finalDamage = rolledDamage;
  let flavor = `失败豁免：造成 ${rolledDamage} 点力场伤害`;
  if (saveTotal >= dc) {
    finalDamage = Math.floor(rolledDamage / 2);
    flavor = `豁免成功：造成减半伤害（${finalDamage}）`;
  }

  // 为了让 MidiQOL 正确显示并应用“最终伤害”，构造一个表示最终伤害的 Roll 对象并传入
  const finalRoll = new Roll(String(finalDamage));
  await finalRoll.evaluate();

  // ========== 调用 MidiQOL DamageOnlyWorkflow ==========
  // 参数： (sourceActor, sourceToken, damageAmount, damageType, targetsArray, rollObject, options)
  await new MidiQOL.DamageOnlyWorkflow(
    sourceActor,                 // 施法者 actor（可能为 null，但通常存在）
    sourceToken ?? null,         // 施法者 token（如果在场景上找不到可传 null）
    finalDamage,                 // 最终数值（number）
    "force",                     // 伤害类型：力场
    [ targetToken ].filter(Boolean), // 目标数组（若找不到 token 可传空）
    finalRoll,                   // Roll 对象 —— 必须反映最终造成的伤害
    { flavor, itemCardId: context?.itemCardId ?? null }
  );

  console.log("伤害应用完成:", finalDamage, flavor);
})();
